import time, itertools, random

HARD = {'num_vars': 7, 'clauses': [[-2, -3, 7], [3, -6, -1], [-1, 2, -5], [5, -2, 4], [3, 1, -2], [4, -7, 5], [-6, -7, -2], [3, 7, 2], [-1, -3, -2], [3, 1, 5], [-3, 5, 4], [-6, 2, 1], [1, 3, -7], [4, -5, -7], [7, 6, -2], [-5, 7, -3], [6, -5, -7], [7, 4, 1]]}

def encode_coloring(inst):
    n=inst['n']
    adj=[set() for _ in range(n)]
    for u,v in inst['edges']: adj[u].add(v); adj[v].add(u)
    # var index: (v,c) -> v*3+c+1
    def X(v,c): return v*3+c+1
    nv=n*3
    clauses=[]
    for v in range(n):
        clauses.append([X(v,0),X(v,1),X(v,2)])
        for a in range(3):
            for b in range(a+1,3):
                clauses.append([-X(v,a),-X(v,b)])
    for u in range(n):
        for v in adj[u]:
            if u<v:
                for c in range(3):
                    clauses.append([-X(u,c),-X(v,c)])
    return nv, clauses

def dpll(nv, clauses, time_limit=30.0):
    t0=time.time()
    # simple DPLL with unit propagation, pure literal, MOMS branching
    def solve(clauses):
        if time.time()-t0>time_limit: raise TimeoutError
        # unit propagation
        assignment={}
        clauses=[list(c) for c in clauses]
        changed=True
        while True:
            # find unit
            unit=None
            for c in clauses:
                if len(c)==1:
                    unit=c[0]; break
            if unit is None: break
            lit=unit
            assignment[abs(lit)]=lit>0
            new=[]
            for c in clauses:
                if lit in c: continue
                if -lit in c:
                    c=[x for x in c if x!=-lit]
                    if not c: return None
                new.append(c)
            clauses=new
        if not clauses: return assignment
        # pure literal
        # MOMS: shortest clause
        minlen=min(len(c) for c in clauses)
        cand=[c for c in clauses if len(c)==minlen]
        # choose literal with max occurrence among these
        from collections import Counter
        cnt=Counter()
        for c in cand:
            for l in c: cnt[l]+=1
        lit=max(cnt, key=lambda l: cnt[l])
        for choice in (lit, -lit):
            res=solve(clauses+[[choice]])
            if res is not None:
                res.update(assignment)
                return res
        return None
    try:
        return solve(clauses)
    except TimeoutError:
        return 'TIMEOUT'

if __name__=='__main__':
    import reduce as R
    red=R.reduce(HARD)
    nv,cl=encode_coloring(red)
    print('n',red['n'],'nv',nv,'nclauses',len(cl))
    t0=time.time()
    res=dpll(nv,cl,time_limit=60)
    print('result', 'SAT' if isinstance(res,dict) else res, 'time %.3f'%(time.time()-t0))
